var DEV = process.env.NODE_ENV !== "production";
var warnings = new Set();
function warnOnce(condition, ...rest) {
    if (DEV && condition) {
        var key = rest.join(" ");
        if (warnings.has(key)) {
            return;
        }
        warnings.add(key);
        console.warn(...rest);
    }
}
module.exports = warnOnce;
